package com.productivitysuite.controller;
import com.productivitysuite.dto.planning.*; import com.productivitysuite.service.DailyPlanService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.core.userdetails.UserDetails; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/plans") @RequiredArgsConstructor public class DailyPlanController { private final DailyPlanService service; @GetMapping public List<PlanResponse> list(@AuthenticationPrincipal UserDetails p,@RequestParam LocalDate date){return service.list(uid(p),date);} @PostMapping public ResponseEntity<PlanResponse> create(@AuthenticationPrincipal UserDetails p,@Valid @RequestBody PlanRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(uid(p),r));} @PostMapping("/{id}/approve") public PlanResponse approve(@AuthenticationPrincipal UserDetails p,@PathVariable UUID id){return service.approve(uid(p),id);} @PostMapping("/{id}/replan") public PlanResponse replan(@AuthenticationPrincipal UserDetails p,@PathVariable UUID id,@Valid @RequestBody PlanRequest r){return service.replan(uid(p),id,r);} @PostMapping("/energy") public ResponseEntity<Void> energy(@AuthenticationPrincipal UserDetails p,@Valid @RequestBody EnergyRequest r){service.logEnergy(uid(p),r);return ResponseEntity.status(HttpStatus.CREATED).build();} private UUID uid(UserDetails p){return UUID.fromString(p.getUsername());} }
